CREATE FUNCTION agri.covariate_feature_schema(p_schema_version character varying) RETURNS TABLE(feature_index integer, feature_name text, feature_kind text, stream_key text, signal_name text, lag_days integer, window_days integer)
    LANGUAGE plpgsql IMMUTABLE
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, MDY'
    SET extra_float_digits TO '1'
    AS $$
        BEGIN
            IF p_schema_version NOT IN ('agri_covariates_v1', 'agri_covariates_v2') THEN
                RAISE EXCEPTION 'unknown covariate schema version %; defined versions are agri_covariates_v1 and agri_covariates_v2', p_schema_version;
            END IF;

            RETURN QUERY
            WITH signal_spec(signal_ordinal, signal_name) AS (
                VALUES
                    (1, 'air_temperature_max'),
                    (2, 'air_temperature_mean'),
                    (3, 'air_temperature_min'),
                    (4, 'dew_point_temperature'),
                    (5, 'precipitation'),
                    (6, 'relative_humidity'),
                    (7, 'wind_speed')
            ),
            shape_spec(shape_ordinal, name_suffix, lag_days, window_days) AS (
                VALUES
                    (1, 'lag_1', 1, 1),
                    (2, 'lag_2', 2, 1),
                    (3, 'lag_3', 3, 1),
                    (4, 'roll_mean_7', 1, 7),
                    (5, 'roll_mean_28', 1, 28)
            ),
            meteorology AS (
                SELECT
                    ((signal_spec.signal_ordinal - 1) * 5 + shape_spec.shape_ordinal) AS feature_index,
                    (signal_spec.signal_name || '_' || shape_spec.name_suffix) AS feature_name,
                    'meteorology' AS feature_kind,
                    'nasa_power' AS stream_key,
                    signal_spec.signal_name AS signal_name,
                    shape_spec.lag_days AS lag_days,
                    shape_spec.window_days AS window_days
                FROM signal_spec
                CROSS JOIN shape_spec
            ),
            derived AS (
                SELECT
                    entry.feature_index,
                    entry.feature_name,
                    entry.feature_kind,
                    entry.stream_key,
                    entry.signal_name,
                    entry.lag_days,
                    entry.window_days
                FROM (
                    VALUES
                        (36, 'drought_severity_class_lag_1', 'drought', 'usdm', NULL::text, 1, 1),
                        (37, 'drought_severity_class_lag_7', 'drought', 'usdm', NULL::text, 7, 1),
                        (38, 'drought_severity_imputed_lag_1', 'drought', 'usdm', NULL::text, 1, 1),
                        (39, 'day_of_year_sin', 'calendar', 'calendar', NULL::text, 0, 1),
                        (40, 'day_of_year_cos', 'calendar', 'calendar', NULL::text, 0, 1)
                ) AS entry(
                    feature_index, feature_name, feature_kind, stream_key,
                    signal_name, lag_days, window_days
                )
            ),
            forecast_derived AS (
                -- v2 only. Indices 1..40 above are byte-identical to v1, so an
                -- agri_covariates_v1 caller sees exactly the vector it always saw and a v2
                -- caller sees that same prefix followed by the forecast-derived block.
                -- Every entry is strictly lagged (lag_days >= 1) or a deterministic function
                -- of the row's own date, so a day-D feature row can never read a day-D issue.
                SELECT
                    entry.feature_index,
                    entry.feature_name,
                    entry.feature_kind,
                    entry.stream_key,
                    entry.signal_name,
                    entry.lag_days,
                    entry.window_days
                FROM (
                    VALUES
                        (41, 'mc_forecast_low_for_day', 'mc_forecast', 'forecast_iteration', NULL::text, 1, 1),
                        (42, 'mc_forecast_median_for_day', 'mc_forecast', 'forecast_iteration', NULL::text, 1, 1),
                        (43, 'mc_forecast_high_for_day', 'mc_forecast', 'forecast_iteration', NULL::text, 1, 1),
                        (44, 'mc_forecast_band_width_for_day', 'mc_forecast', 'forecast_iteration', NULL::text, 1, 1),
                        (45, 'mc_forecast_lead_days', 'mc_forecast', 'forecast_iteration', NULL::text, 1, 1),
                        (46, 'day_of_year_sin_semiannual', 'calendar', 'calendar', NULL::text, 0, 1),
                        (47, 'day_of_year_cos_semiannual', 'calendar', 'calendar', NULL::text, 0, 1)
                ) AS entry(
                    feature_index, feature_name, feature_kind, stream_key,
                    signal_name, lag_days, window_days
                )
                WHERE p_schema_version = 'agri_covariates_v2'
            )
            SELECT
                combined.feature_index::integer,
                combined.feature_name::text,
                combined.feature_kind::text,
                combined.stream_key::text,
                combined.signal_name::text,
                combined.lag_days::integer,
                combined.window_days::integer
            FROM (
                SELECT * FROM meteorology
                UNION ALL
                SELECT * FROM derived
                UNION ALL
                SELECT * FROM forecast_derived
            ) AS combined
            ORDER BY combined.feature_index;
        END
        $$;
